const KEY='astoria-campaign-v1';
const LEGACY_KEY='northline-campaign-v1';
const initial=()=>({headline:'Make room for your daily ritual.',version:1,revisionPending:false,direction:'ritual',directionApproved:true,brief:{audience:'Adults looking for a simpler daily skincare routine.',objective:'Introduce Solune Daily Moisturizer and invite visitors to join the launch list.',facts:'Product name: Solune Daily Moisturizer. A fictional skincare product. No clinical or efficacy claims are approved.'},scenes:[true,true,true,true,false,false].map(approved=>({approved,version:1,comments:[]})),assets:[true,true,false,false,false,false].map(approved=>({approved,version:1,comments:[]})),site:{built:false,approved:false,version:1,headline:'Make room for your daily ritual.'},activity:[{text:'Storyboard ready for review',detail:'6 scenes · concept visuals'},{text:'First graphics approved',detail:'2 of 6 assets · reviewer'},{text:'Creative direction selected',detail:'The Daily Ritual · producer'}]});
let state;try{state=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem(LEGACY_KEY))||initial();if(!state.scenes||state.scenes.length!==6||!state.assets||state.assets.length!==6)state=initial()}catch{state=initial()}
let page='overview',filter='all',mobile=false,toastTimer,productionBusy=false;
const main=document.getElementById('main'),dialog=document.getElementById('dialog');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));document.getElementById('save-label').textContent='Saved locally'}catch{document.getElementById('save-label').textContent='Session only'}}
function activity(text,detail){state.activity.unshift({text,detail});state.activity=state.activity.slice(0,8)}
function toast(message){document.getElementById('toast').textContent=message;document.getElementById('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.getElementById('toast').classList.remove('visible'),4200)}
function product(id='p',color='#e9e5d9'){return `<svg class="product-svg" viewBox="0 0 440 300" role="img" aria-label="Illustrated Solune moisturizer jar on a sculptural pedestal"><defs><linearGradient id="${id}jar" x1="0" x2="1"><stop stop-color="#c8c3b3"/><stop offset=".35" stop-color="${color}"/><stop offset=".65" stop-color="#f8f5ec"/><stop offset="1" stop-color="#cfc7b5"/></linearGradient><linearGradient id="${id}base" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#e9e3f0"/><stop offset="1" stop-color="#b7a9c8"/></linearGradient><filter id="${id}shadow"><feGaussianBlur stdDeviation="7"/></filter></defs><ellipse cx="260" cy="272" rx="116" ry="13" fill="#796588" opacity=".18" filter="url(#${id}shadow)"/><path d="M140 235L318 209L362 246L184 280Z" fill="#e9e2f0"/><path d="M184 280L362 246V274L184 302Z" fill="url(#${id}base)"/><path d="M140 235L184 280V302L140 256Z" fill="#b9accb"/><g transform="rotate(-7 252 165)"><ellipse cx="251" cy="221" rx="74" ry="15" fill="#aea58f"/><path d="M177 133H325V221Q251 249 177 221Z" fill="url(#${id}jar)"/><ellipse cx="251" cy="133" rx="74" ry="16" fill="#d5cfbf"/><path d="M174 115Q251 89 328 115V139Q251 163 174 139Z" fill="url(#${id}jar)"/><ellipse cx="251" cy="114" rx="77" ry="17" fill="#f4f0e4"/><ellipse cx="251" cy="114" rx="69" ry="12" fill="none" stroke="#ded7c7"/><text x="251" y="185" text-anchor="middle" font-family="Georgia,serif" font-size="24" fill="#61576b" letter-spacing="2">solune</text><text x="251" y="199" text-anchor="middle" font-family="Arial,sans-serif" font-size="5.5" fill="#7b7185" letter-spacing="1.1">DAILY MOISTURIZER</text><text x="251" y="216" text-anchor="middle" font-family="Arial,sans-serif" font-size="5" fill="#7b7185">A MOMENT FOR YOU.</text></g><path d="M369 204Q386 136 350 100Q369 132 369 204" fill="#7d8961" opacity=".8"/><path d="M369 178Q407 139 403 117Q383 132 369 178" fill="#8b9677"/><path d="M370 202Q419 183 415 160Q389 168 370 202" fill="#a0a98d"/></svg>`}
const sceneData=[{name:'A moment of stillness',duration:3,copy:'A quieter start.',notes:'Soft morning light. Linen and a slow-moving shadow.',style:'linen'},{name:'Meet the daily ritual',duration:4,copy:()=>state.headline,notes:'Hero product reveal. Gentle push-in on the jar.',style:'product'},{name:'The details',duration:3,copy:'Solune Daily Moisturizer.',notes:'Close-up of the packaging. Keep the label readable.',style:'detail'},{name:'Space for yourself',duration:4,copy:'One moment. Just for you.',notes:'Product on a clean bathroom shelf. Warm neutral tones.',style:'shelf'},{name:'Make it yours',duration:3,copy:'Your routine, your rhythm.',notes:'Return to the product. Leave space for on-screen copy.',style:'product'},{name:'The invitation',duration:3,copy:'Join the launch list.',notes:'Logo end card with CTA. Hold for readability.',style:'end'}];
const sizes=['1080 × 1080','1080 × 1350','1080 × 1920'];
const assetName=i=>`${i<3?'Ritual hero':'Product spotlight'} · ${['Square','Portrait','Vertical'][i%3]}`;
function badge(item){return `<span class="badge ${(state.revisionPending&&!item.approved)?'stale':item.approved?'approved':''}">${(state.revisionPending&&!item.approved)?'Needs rebuild':item.approved?'Approved':'In review'} · v${item.version}</span>`}
function heading(eyebrow,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow"><i></i>${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function revisionNote(){return state.revisionPending?`<div class="note warning">Copy revision v${state.version} is pending. Affected approvals are stale. <button class="text-button" data-action="regenerate">Rebuild affected deliverables →</button></div>`:''}
function overview(){const approved=state.scenes.filter(s=>s.approved).length+state.assets.filter(a=>a.approved).length;return heading('SOLUNE / PRODUCT LAUNCH','Every brand has a story.','Bring yours to life, from the first idea to the final handoff.',`<button class="button" data-action="go" data-target="review">Open review queue <span>↗</span></button>`)+revisionNote()+`<section class="hero"><div class="hero-copy"><span class="tag">CAMPAIGN 001 · IN PRODUCTION</span><h2>${esc(state.headline)}</h2><p>A considered launch for Solune. Quiet visuals, intentional storytelling, a little space for yourself.</p><button class="button light" data-action="go" data-target="brief">Explore campaign brief <span>↗</span></button></div><div class="hero-art">${product('hero')}<span class="art-caption">SOLUNE · THE DAILY RITUAL</span></div></section><div class="stats"><div class="stat"><div class="stat-top"><span>Creative direction</span><span>✳</span></div><div class="stat-value">01 <small>/ 02 concepts</small></div><div class="stat-foot">● ${state.directionApproved?'Direction approved':'Direction in review'}</div></div><div class="stat"><div class="stat-top"><span>Storyboard</span><span>▤</span></div><div class="stat-value">06 <small>scenes · 20 seconds</small></div><div class="stat-foot">${state.scenes.filter(s=>s.approved).length} of 6 scenes approved</div></div><div class="stat"><div class="stat-top"><span>Campaign assets</span><span>▧</span></div><div class="stat-value">06 <small>graphics · 3 formats</small></div><div class="stat-foot">${state.assets.filter(s=>s.approved).length} of 6 graphics approved</div></div><div class="stat"><div class="stat-top"><span>Approval progress</span><span>◉</span></div><div class="stat-value">${Math.round(approved/12*100)}<small>% reviewed</small></div><div class="progress-bar"><div style="width:${approved/12*100}%"></div></div></div></div><div class="overview-bottom"><section><div class="section-title"><h2>The production path</h2><a href="#delivery">View deliverables ↗</a></div><div class="panel"><div class="pipeline">${['Brief','Direction','Storyboard','Assets','Website','Delivery'].map((x,i)=>`<a href="#${['brief','direction','storyboard','assets','website','delivery'][i]}" class="pipeline-step ${i<2?'done':i===2?'current':''}"><span class="circle">${i<2?'✓':i+1}</span>${x}</a>`).join('')}</div><div class="next-action"><div><strong>${state.revisionPending?'Your revision is ready to rebuild':'A fresh pair of eyes.'}</strong><p>${state.revisionPending?'Carry the new headline into the campaign.':'Review your scenes and graphics before building the website.'}</p></div><button class="button secondary" data-action="${state.revisionPending?'regenerate':'go'}" data-target="storyboard">${state.revisionPending?'Rebuild outputs':'Review storyboard'} →</button></div></div></section><section><div class="section-title"><h2>Inside Astoria</h2><span class="outline-label">RECENT ACTIVITY</span></div><div class="panel activity">${state.activity.slice(0,3).map((a,i)=>`<div class="activity-row"><span class="activity-icon">${['▤','✓','✳'][i]}</span><div><strong>${esc(a.text)}</strong><p>${esc(a.detail)}</p></div></div>`).join('')}</div></section></div>`}
function brief(){return heading('01 / DISCOVERY','The campaign brief.','A shared starting point for every creative decision.',`<button class="button" data-action="save-brief">Save brief <span>✓</span></button>`)+`<div class="brief-layout"><div class="panel"><div class="section-title"><h2>Solune · Daily Ritual</h2><span class="badge ready">Fictional campaign</span></div><div class="field"><label for="headline">Approved campaign headline</label><input id="headline" maxlength="110" value="${esc(state.headline)}"><small>Changing this copy marks dependent scenes, graphics, and the website for revision.</small></div><div class="field"><label for="audience">Who are we speaking to?</label><textarea id="audience" maxlength="600">${esc(state.brief.audience)}</textarea></div><div class="field"><label for="objective">Campaign objective</label><textarea id="objective" maxlength="600">${esc(state.brief.objective)}</textarea></div><div class="field"><label for="facts">Approved product facts</label><textarea id="facts" maxlength="1200">${esc(state.brief.facts)}</textarea><small>Draft creative must remain within the supplied facts.</small></div><div class="note">This mockup uses seeded materials. File intake and MCP production will be connected in the implementation milestone.</div></div><div><div class="panel"><div class="section-title"><h2>The brand kit</h2><span>↗</span></div><div class="swatches"><div class="swatch" style="background:#dcd5eb" title="Lavender #DCD5EB"></div><div class="swatch" style="background:#efe9dd" title="Oat #EFE9DD"></div><div class="swatch" style="background:#818c70" title="Sage #818C70"></div><div class="swatch" style="background:#51415f" title="Plum #51415F"></div></div><p style="font-size:11px;color:var(--muted)">Lavender, oat, sage, and a touch of plum.<br>Editorial serif + clean sans serif.</p>${[['▧','Product illustration','SVG · original demo artwork'],['Aa','Solune wordmark','Text-based · demo identity'],['☷','Approved campaign copy','Structured data · version '+state.version]].map(a=>`<div class="asset-item"><span class="file-icon">${a[0]}</span><div><strong>${a[1]}</strong><small>${a[2]}</small></div></div>`).join('')}</div><div class="panel" style="margin-top:18px"><div class="section-title"><h2>What we’re making</h2></div><div class="metric-list"><div><strong>6 scenes</strong><small>A 20-second social video storyboard</small></div><div><strong>6 graphics</strong><small>Two layouts, three social formats</small></div><div><strong>1 microsite</strong><small>A responsive launch experience</small></div></div></div></div></div>`}
function direction(){return heading('02 / CONCEPT','Find the feeling.','Two starting points. One coherent direction for the whole campaign.')+`<div class="grid two">${[{id:'ritual',name:'The Daily Ritual',headline:'Make room for your daily ritual.',desc:'Soft light, sculptural product compositions, and quiet editorial copy. A little breathing room in a busy feed.'},{id:'simple',name:'Simply Solune',headline:'Less noise. More you.',desc:'Sage tones, spacious layouts, and direct product storytelling. A fresh, pared-back take on the daily routine.'}].map((d,i)=>`<article class="card"><div class="direction-cover ${i?'alt':''}"><div class="eyebrow" style="margin-bottom:18px">CONCEPT 0${i+1}</div><h2>${d.headline}</h2>${product('direction'+i)}</div><div class="card-content"><div class="card-meta"><span>CREATIVE DIRECTION</span><span class="badge ${state.direction===d.id?'approved':''}">${state.direction===d.id?(state.directionApproved?'Selected & approved':'Selected · in review'):'Alternative'}</span></div><h3>${d.name}</h3><p>${d.desc}</p><button class="button ${state.direction===d.id?'secondary':''}" data-action="select-direction" data-id="${d.id}">${state.direction===d.id?'Selected direction ✓':'Select this direction →'}</button>${state.direction===d.id&&!state.directionApproved?'<button class="button light" data-action="approve-direction">Approve direction ✓</button>':''}</div></article>`).join('')}</div><div class="note" style="margin-top:20px">Switching direction requires a new storyboard and asset treatment. In this prototype, switching marks existing deliverables stale and rebuilds the seeded treatment.</div>`}
function sceneVisual(i){const d=sceneData[i];if(d.style==='linen')return `<svg viewBox="0 0 440 300" class="product-svg" role="img" aria-label="Illustrated morning shadows on linen"><rect width="440" height="300" fill="#e8dfd1"/><path d="M-10 20L330 300M60 -10L400 300M150 -10L480 280" stroke="#bcb39f" stroke-width="29" opacity=".3"/><path d="M0 240Q120 140 220 190T440 190" fill="none" stroke="#f7f2e8" stroke-width="50" opacity=".6"/><text x="34" y="70" fill="#6f6457" font-family="Georgia" font-size="25">A quieter start.</text></svg>`;if(d.style==='end')return `<svg viewBox="0 0 440 300" class="product-svg" role="img" aria-label="Solune logo and launch invitation"><rect width="440" height="300" fill="#dcd4eb"/><text x="220" y="140" text-anchor="middle" font-family="Georgia" font-size="59" fill="#51415f">solune</text><text x="220" y="180" text-anchor="middle" font-family="Arial" font-size="12" fill="#756584" letter-spacing="3">JOIN THE LAUNCH LIST</text><circle cx="220" cy="219" r="16" fill="none" stroke="#a898b8"/><text x="220" y="225" text-anchor="middle" font-size="20" fill="#756584">↗</text></svg>`;return product('scene'+i)}
function storyboard(){return heading('03 / STORYBOARD','A story in six moments.','The Daily Ritual · 20-second social concept · illustrative visuals',`<button class="button secondary" data-action="export-storyboard">Download storyboard ↓</button>`)+revisionNote()+`<div class="preview-strip"><span>▤ &nbsp; Six scenes · 3 + 4 + 3 + 4 + 3 + 3 seconds</span><span class="badge ready">Storyboard only</span></div><div class="grid three">${sceneData.map((d,i)=>`<article class="card"><div class="card-art" style="background:${['#e8dfd1','#ded6ef','#e9e3d8','#e5e7d3','#dcd4eb','#dcd4eb'][i]}">${sceneVisual(i)}</div><div class="card-content"><div class="scene-top"><span>SCENE 0${i+1} · ${d.duration}s</span>${badge(state.scenes[i])}</div><h3>${d.name}</h3><div class="scene-copy">“${esc(typeof d.copy==='function'?d.copy():d.copy)}”</div><div class="scene-notes">${d.notes}</div><div class="card-actions"><button class="button secondary" data-action="approve" data-kind="scenes" data-index="${i}" ${state.scenes[i].approved||state.revisionPending?'disabled':''}>${state.scenes[i].approved?'Approved ✓':'Approve scene'}</button><button class="text-button" data-action="comment" data-kind="scenes" data-index="${i}">Comments (${state.scenes[i].comments.length})</button></div></div></article>`).join('')}</div>`}
function assetArt(i){return `<div class="card-art ${['square','portrait','vertical'][i%3]} ${i>2?'art-layout-minimal':''}"><div class="art-title">${esc(i<3?state.headline:'A moment for you.')}</div>${product('asset'+i)}<span style="position:absolute;bottom:12px;right:16px;font:18px Georgia;color:#665775">solune</span></div>`}
function assets(){return heading('04 / PRODUCTION','Made for every moment.','Two layouts. Three formats. One consistent campaign.',`<button class="button secondary" data-action="regenerate">${state.revisionPending?'Rebuild affected assets':'Simulate production'} ↻</button>`)+revisionNote()+`<div class="filter-row">${['all','approved','review'].map(f=>`<button class="filter ${filter===f?'active':''}" data-action="filter" data-filter="${f}">${{all:'All assets',approved:'Approved',review:'In review'}[f]}</button>`).join('')}</div><div class="grid three asset-grid">${state.assets.map((a,i)=>({a,i})).filter(({a})=>filter==='all'||(filter==='approved'?a.approved:!a.approved)).map(({a,i})=>`<article class="card">${assetArt(i)}<div class="card-content"><div class="card-meta"><span>${sizes[i%3]} · SVG DEMO</span>${badge(a)}</div><h3>${assetName(i)}</h3><p>Editable illustration · ${i<3?'campaign headline':'product-led composition'}</p><div class="card-actions"><button class="button secondary" data-action="approve" data-kind="assets" data-index="${i}" ${a.approved||state.revisionPending?'disabled':''}>${a.approved?'Approved ✓':'Approve asset'}</button><button class="text-button" data-action="download-asset" data-index="${i}">Download ↓</button></div></div></article>`).join('')||'<div class="empty">No assets in this view yet.</div>'}</div><p class="motion-note">These are original SVG mockups. PhotoCraft MCP rendering is not connected.</p>`}
function review(){const rows=[...state.scenes.map((s,i)=>({s,i,kind:'scenes',name:sceneData[i].name})),...state.assets.map((s,i)=>({s,i,kind:'assets',name:assetName(i)}))].filter(x=>!x.s.approved);return heading('05 / REVIEW','A fresh pair of eyes.','Approve exact versions. Keep feedback attached to the work.',`<button class="button secondary" data-action="revise">Request copy revision ↗</button>`)+revisionNote()+`<div class="note">Demo reviewer mode. Approval actions represent a client review; production authentication will come later.</div><div class="panel"><div class="section-title"><h2>${rows.length} deliverables need a decision</h2><span class="outline-label">REVIEWER VIEW</span></div>${rows.map(({s,i,kind,name})=>`<div class="review-row"><div class="review-thumb">${product('review'+kind+i)}</div><div class="review-info"><h3>${esc(name)}</h3><p>${kind==='scenes'?'Storyboard scene':'Campaign graphic'} · v${s.version} · ${s.comments.length} comments</p></div>${badge(s)}<button class="button secondary" data-action="comment" data-kind="${kind}" data-index="${i}">Comment</button><button class="button" data-action="approve" data-kind="${kind}" data-index="${i}" ${state.revisionPending?'disabled':''}>Approve ✓</button></div>`).join('')||'<div class="empty">✓ All scenes and graphics are approved. Your campaign is ready for a website preview.<br><br><a class="button" href="#website">Build the campaign website ↗</a></div>'}</div>`}
function website(){const ready=allCreativeApproved();return heading('06 / WEBSITE','Give the campaign a home.','A responsive microsite assembled from the approved campaign.',`<button class="button" data-action="build-site" ${!ready||state.revisionPending?'disabled':''}>${state.site.built?'Rebuild preview':'Build campaign preview'} ↗</button>`)+revisionNote()+(!ready?'<div class="note">Approve the creative direction, all six scenes, and all six graphics to build the microsite.</div>':'')+(state.site.built?`<div class="website-tools"><div class="button-row"><button class="filter ${!mobile?'active':''}" data-action="viewport" data-mobile="false">Desktop</button><button class="filter ${mobile?'active':''}" data-action="viewport" data-mobile="true">Mobile</button></div><div class="button-row"><span class="badge ${state.site.approved?'approved':''}">${state.revisionPending?'Stale preview':state.site.approved?'Approved':'In review'} · v${state.site.version}</span><button class="button secondary" data-action="approve-site" ${state.site.approved||state.revisionPending||!ready||state.site.version!==state.version?'disabled':''}>${state.site.approved?'Website approved ✓':'Approve website'}</button><button class="button secondary" data-action="download-site" ${!state.site.approved||state.revisionPending?'disabled':''}>Export HTML ↓</button></div></div><div class="website-browser ${mobile?'mobile':''}"><div class="browser-bar"><i class="browser-dot"></i><i class="browser-dot"></i><i class="browser-dot"></i><span class="browser-url">solune / daily-ritual · local demo</span><button data-action="fullscreen" aria-label="Open campaign preview in a dialog">↗</button></div><iframe id="site-frame" title="Solune campaign microsite preview" sandbox="allow-scripts"></iframe></div>`:`<div class="card"><div class="direction-cover" style="min-height:340px"><div class="eyebrow">SOLUNE · CAMPAIGN MICROSITE</div><h2 style="margin-top:20px">A home for the<br>daily ritual.</h2>${product('site-empty')}</div><div class="card-content"><h3>Everything connects.</h3><p>Your selected direction, approved headline, and campaign imagery become a launch page. Review the responsive preview, then export a standalone HTML file.</p><div class="card-meta"><span>Hero · Brand story · Campaign gallery · Demo CTA</span><span class="badge">Not built yet</span></div></div></div>`)}
function allCreativeApproved(){return state.directionApproved&&state.scenes.every(s=>s.approved)&&state.assets.every(a=>a.approved)&&!state.revisionPending}
function deliveryReady(){return allCreativeApproved()&&state.site.built&&state.site.approved&&state.site.version===state.version}
function delivery(){const ready=deliveryReady();return heading('07 / HANDOFF','Ready for the world.','A considered handoff, with every decision accounted for.')+`<div class="grid two"><div class="panel"><div class="section-title"><h2>Delivery checklist</h2><span class="badge ${ready?'approved':''}">${ready?'Ready to deliver':'Approvals needed'}</span></div>${[['Creative direction',state.directionApproved],['Six storyboard scenes',state.scenes.every(s=>s.approved)&&!state.revisionPending],['Six campaign graphics',state.assets.every(a=>a.approved)&&!state.revisionPending],['Current campaign website',state.site.approved&&state.site.version===state.version&&!state.revisionPending]].map(([name,ok])=>`<div class="delivery-check"><span>${name}</span><span class="badge ${ok?'approved':''}">${ok?'Approved ✓':'Pending'}</span></div>`).join('')}<p class="motion-note">Approval is tied to an exact version. Revised material must be reviewed again before handoff.</p><a class="button secondary" href="#review" style="margin-top:15px">Go to review queue →</a></div><div class="panel"><div class="delivery-icon">↧</div><h2 style="font:600 22px Manrope;letter-spacing:-.5px;margin:0 0 10px">The complete campaign.</h2><p style="font-size:12px;color:var(--muted)">One ZIP with six SVG graphics, the storyboard, a standalone microsite, and a manifest tracing the delivered versions.</p><button class="button" data-action="download-bundle" ${!ready?'disabled':''}>Download campaign bundle ↓</button><p class="motion-note">Original illustration assets and synthetic campaign content. No live MCP calls or external publishing.</p></div></div>`}
function render(){document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));document.getElementById('review-count').textContent=state.scenes.filter(x=>!x.approved).length+state.assets.filter(x=>!x.approved).length;main.innerHTML=({overview,brief,direction,storyboard,assets,review,website,delivery}[page]||overview)();if(page==='website'&&state.site.built)document.getElementById('site-frame').srcdoc=siteHTML(state.site.headline);persist()}
function route(){const target=location.hash.slice(1)||'overview';page=['overview','brief','direction','storyboard','assets','review','website','delivery'].includes(target)?target:'overview';render();window.scrollTo(0,0)}
function setHeadline(next){next=next.trim();if(!next)return toast('Enter a campaign headline.');if(next===state.headline)return false;state.headline=next;state.version++;state.revisionPending=true;state.scenes[1].approved=false;state.assets.slice(0,3).forEach(a=>a.approved=false);state.site.approved=false;activity('Campaign copy revised','v'+state.version+' · dependent approvals marked stale');persist();return true}
function approve(kind,i){if(state.revisionPending)return toast('Rebuild the revised outputs before approving.');state[kind][i].approved=true;activity((kind==='scenes'?'Scene':'Graphic')+' approved',`${kind==='scenes'?sceneData[i].name:assetName(i)} · v${state[kind][i].version}`);render();toast('Version approved.');}
function openDialog(html){document.getElementById('dialog-content').innerHTML=html;dialog.showModal()}
function revise(){openDialog(`<h2>A new line, a connected campaign.</h2><p>Update the headline. Scene 02, the three hero graphics, and the website will need a new review. Other approvals stay intact.</p><div class="field"><label for="revision-headline">New campaign headline</label><input id="revision-headline" maxlength="110" value="${esc(state.headline)}"></div><button class="text-button" data-action="suggest-headline">Use “A simple moment, every day.”</button><div class="button-row" style="margin-top:24px"><button class="button" data-action="commit-revision">Apply revision →</button><button class="button secondary" data-action="close">Cancel</button></div>`)}
async function regenerate(){if(productionBusy)return;productionBusy=true;toast('Simulating a local production job…');document.querySelectorAll('[data-action="regenerate"]').forEach(b=>{b.disabled=true;b.classList.add('loading')});await new Promise(r=>setTimeout(r,1200));if(state.revisionPending){state.scenes[1].version=state.version;state.assets.slice(0,3).forEach(a=>a.version=state.version);state.revisionPending=false;activity('Affected deliverables rebuilt','Scene 02 + 3 hero graphics · review required');}else activity('Production simulation complete','6 seeded graphics · no MCP connection');productionBusy=false;render();toast('Production complete. Review updated outputs.');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,i=Number(b.dataset.index),kind=b.dataset.kind;
if(a==='go')location.hash=b.dataset.target;
if(a==='save-brief'){const headline=document.getElementById('headline').value.trim();if(!headline)return toast('A headline is required.');state.brief={audience:document.getElementById('audience').value.trim(),objective:document.getElementById('objective').value.trim(),facts:document.getElementById('facts').value.trim()};if(!Object.values(state.brief).every(Boolean))return toast('Complete all brief fields.');const changed=setHeadline(headline);render();toast(changed?'Brief saved. Rebuild the affected campaign outputs.':'Brief saved locally.');}
if(a==='select-direction'){if(state.direction===b.dataset.id)return toast('This direction is already selected.');state.direction=b.dataset.id;state.directionApproved=false;state.version++;state.revisionPending=true;state.scenes.forEach(s=>s.approved=false);state.assets.forEach(s=>s.approved=false);state.site.approved=false;state.scenes.forEach(s=>s.version=state.version);state.assets.forEach(s=>s.version=state.version);activity('Creative direction changed','All creative requires review · seeded treatment');render();toast('Direction selected. Approve it and rebuild the seeded treatment.');}
if(a==='approve-direction'){state.directionApproved=true;activity('Direction approved','v'+state.version);render();toast('Creative direction approved.');}
if(a==='approve')approve(kind,i);
if(a==='filter'){filter=b.dataset.filter;render()}
if(a==='revise')revise();
if(a==='suggest-headline')document.getElementById('revision-headline').value='A simple moment, every day.';
if(a==='commit-revision'){const next=document.getElementById('revision-headline').value.trim();if(!next)return toast('Enter a headline.');const changed=setHeadline(next);dialog.close();render();toast(changed?'Revision applied. Rebuild affected deliverables.':'Headline is unchanged.');}
if(a==='regenerate')await regenerate();
if(a==='close')dialog.close();
if(a==='comment'){const item=state[kind][i];openDialog(`<h2>Notes on ${esc(kind==='scenes'?sceneData[i].name:assetName(i))}</h2><p>Feedback stays attached to this deliverable.</p>${item.comments.map(c=>`<div class="comment"><small>Demo reviewer · v${c.version}</small>${esc(c.text)}</div>`).join('')||'<p>No comments yet.</p>'}<div class="field"><label for="comment-text">Add a comment</label><textarea id="comment-text" maxlength="1000" placeholder="What could make this stronger?"></textarea></div><div class="button-row"><button class="button" data-action="save-comment" data-kind="${kind}" data-index="${i}">Add comment</button><button class="button secondary" data-action="close">Done</button></div>`)}
if(a==='save-comment'){const t=document.getElementById('comment-text').value.trim();if(!t)return toast('Write a comment first.');state[kind][i].comments.push({text:t,version:state[kind][i].version});activity('Review feedback added',kind==='scenes'?sceneData[i].name:assetName(i));persist();dialog.close();render();toast('Comment saved.');}
if(a==='build-site'){if(!allCreativeApproved())return toast('Approve all creative first.');state.site={built:true,approved:false,version:state.version,headline:state.headline};activity('Microsite preview assembled','Approved campaign materials · v'+state.version);render();toast('Preview ready for review.');}
if(a==='approve-site'){if(!allCreativeApproved()||state.site.version!==state.version)return toast('Rebuild the website using current approved materials.');state.site.approved=true;activity('Microsite approved','v'+state.site.version+' · ready for handoff');render();toast('Website approved. Delivery is ready.');}
if(a==='viewport'){mobile=b.dataset.mobile==='true';render()}
if(a==='fullscreen'){openDialog('<h2>Solune · Campaign preview</h2><iframe id="dialog-frame" title="Expanded microsite preview" sandbox="allow-scripts" style="height:65vh;border-radius:8px"></iframe><button class="button secondary" data-action="close" style="margin-top:15px">Close preview</button>');document.getElementById('dialog-frame').srcdoc=siteHTML(state.site.headline)}
if(a==='download-site'){if(!deliveryReady())return toast('Approve the current website before export.');download('solune-campaign.html',siteHTML(state.site.headline),'text/html');toast('Standalone website downloaded.');}
if(a==='download-asset'){download(`solune-${i<3?'hero':'spotlight'}-${['square','portrait','vertical'][i%3]}-v${state.assets[i].version}.svg`,assetSVG(i),'image/svg+xml');toast('SVG mockup downloaded.');}
if(a==='export-storyboard'){download('solune-storyboard.html',storyboardHTML(),'text/html');toast('Storyboard downloaded.');}
if(a==='download-bundle'){if(!deliveryReady())return toast('Complete current approvals before delivery.');const files=[{name:'solune-campaign.html',content:siteHTML(state.site.headline)},{name:'storyboard.html',content:storyboardHTML()},{name:'manifest.json',content:JSON.stringify(manifest(),null,2)},...state.assets.map((s,j)=>({name:`assets/solune-${j<3?'hero':'spotlight'}-${['square','portrait','vertical'][j%3]}-v${s.version}.svg`,content:assetSVG(j)}))];download('solune-campaign-v'+state.version+'.zip',zip(files),'application/zip');activity('Campaign bundle exported','v'+state.version+' · 9 files');render();toast('Campaign ZIP downloaded.');}
});
document.getElementById('reset').onclick=()=>openDialog('<h2>Start fresh?</h2><p>This clears your local comments, revisions, and approvals and restores the example campaign.</p><div class="button-row"><button class="button" id="confirm-reset">Reset demo</button><button class="button secondary" data-action="close">Keep working</button></div>');
document.addEventListener('click',e=>{if(e.target.id==='confirm-reset'){state=initial();filter='all';dialog.close();render();toast('Demo reset.')}});
document.getElementById('help').onclick=()=>openDialog('<h2>Astoria. A home for brand stories.</h2><p>Astoria connects creative briefs, storyboards, campaign assets, and launch websites in one workspace. This is an interactive FDE portfolio prototype for a fictional creative agency. Explore the brief, approve deliverables, request a headline revision, and assemble the campaign microsite.</p><p>Creative production is simulated using original SVG illustrations. PhotoCraft and ArtCraft MCP services are not connected. State is saved in this browser; the launch-list CTA collects no data.</p><button class="button" data-action="close">Back to Astoria →</button>');
function download(name,content,type){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function assetSVG(i){const w=1080,h=[1080,1350,1920][i%3],title=i<3?state.headline:'A moment for you.';const words=title.split(' '),lines=[];let line='';for(const word of words){if((line+' '+word).trim().length>22){lines.push(line);line=word}else line=(line+' '+word).trim()}if(line)lines.push(line);return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><rect width="100%" height="100%" fill="${['#dcd4eb','#e8e9d5','#e7ddcf'][i%3]}"/><text x="75" y="110" font-family="Georgia" font-size="45" fill="#51415f">solune</text>${lines.map((l,j)=>`<text x="75" y="${240+j*77}" font-family="Georgia" font-size="66" fill="#51415f">${esc(l)}</text>`).join('')}<svg x="0" y="${h*.38}" width="1080" height="${h*.56}" viewBox="0 0 440 300">${product('export'+i).replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'')}</svg><text x="75" y="${h-55}" font-family="Arial" font-size="19" letter-spacing="3" fill="#756584">FICTIONAL CAMPAIGN · ORIGINAL ILLUSTRATION</text></svg>`}
function manifest(){return {product:'Astoria',campaign:'Solune Daily Ritual',demo:true,toolIntegration:'Simulated; MCP not connected',campaignVersion:state.version,headline:state.headline,direction:state.direction,exportedAt:new Date().toISOString(),storyboard:state.scenes.map((s,i)=>({scene:i+1,title:sceneData[i].name,version:s.version,approved:s.approved,source:i===1?'campaign-headline-v'+state.version:'seeded-scene-copy-v1'})),graphics:state.assets.map((a,i)=>({name:assetName(i),version:a.version,approved:a.approved,source:i<3?'campaign-headline-v'+state.version:'seeded-product-copy-v1',template:i<3?'ritual-hero-v1':'product-spotlight-v1',format:'SVG'})),website:{version:state.site.version,approved:state.site.approved,sourceHeadlineVersion:state.version,template:'solune-microsite-v1'}}}
function storyboardHTML(){return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solune · Storyboard</title><style>body{font:15px Arial;color:#51415f;background:#f7f4ee;max-width:1000px;margin:auto;padding:40px}h1{font:44px Georgia}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:24px}article{background:white;padding:20px;border:1px solid #ded8e6;border-radius:12px}svg{width:100%;height:220px;background:#ded6ef}p{line-height:1.6}@media(max-width:600px){.grid{grid-template-columns:1fr}body{padding:20px}}</style><h1>Six moments. One daily ritual.</h1><p>Fictional Solune campaign · 20 seconds · storyboard concept, not finished video</p><div class="grid">${sceneData.map((d,i)=>`<article>${sceneVisual(i)}<h2>0${i+1} · ${d.name}</h2><p>${d.duration} seconds · v${state.scenes[i].version} · ${state.scenes[i].approved?'Approved':'Draft'}</p><p>“${esc(typeof d.copy==='function'?d.copy():d.copy)}”</p><p>${d.notes}</p></article>`).join('')}</div></html>`}
function siteHTML(headline){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solune · The daily ritual</title><style>*{box-sizing:border-box}body{margin:0;background:#f7f3ec;color:#51415f;font:14px Arial,sans-serif}a{color:inherit;text-decoration:none}nav{padding:24px 6%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #dcd5e1}.logo{font:34px Georgia;letter-spacing:2px}nav a{font-size:10px;letter-spacing:1px}.demo{background:#e6e9d5;text-align:center;padding:8px;font-size:9px;color:#677254;letter-spacing:1px}.hero{display:grid;grid-template-columns:1fr 1fr;min-height:490px;background:#ddd5ec;overflow:hidden}.copy{padding:65px 12%;align-self:center}.label{font-size:9px;letter-spacing:2px;text-transform:uppercase}.copy h1{font:clamp(38px,5vw,68px)/1.04 Georgia;letter-spacing:-1.5px;margin:23px 0}.copy p{font-size:12px;line-height:1.8;max-width:300px}.art{position:relative;display:grid;place-items:center;background:radial-gradient(ellipse at center,#c3b5d9,transparent 70%)}svg{width:100%;height:100%;max-height:450px}.cta{display:inline-block;background:#51415f;border:0;color:white;padding:15px 22px;border-radius:2px;font-size:11px;margin-top:15px;cursor:pointer}.intro{padding:70px 8%;display:grid;grid-template-columns:1fr 1.4fr;gap:60px;border-bottom:1px solid #ddd6ce}.intro h2{font:36px/1.15 Georgia;margin:0}.intro p{font-size:13px;line-height:1.9;margin:0;color:#807387}.features{display:grid;grid-template-columns:repeat(3,1fr);padding:40px 8%;gap:30px}.features strong{font:22px Georgia;display:block;margin:12px 0}.features p{font-size:11px;line-height:1.7;color:#807387}.story{padding:55px 8%;background:#e9e8db}.story h2{font:36px Georgia;margin:12px 0 25px}.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.tile{height:230px;background:#dcd4eb;border-radius:2px;overflow:hidden;position:relative}.tile span{position:absolute;left:15px;top:15px;font:20px Georgia;max-width:70%}.tile svg{transform:translateY(20px)}.caption{font-size:9px;color:#81758b;margin-top:12px}.signup{text-align:center;padding:65px 20px;background:#ded6eb}.signup h2{font:42px Georgia;margin:0 0 14px}.signup p{font-size:12px;color:#7b6a87}.signup button{margin-top:10px}.signup small{display:block;font-size:9px;margin-top:17px;color:#7b6a87}footer{padding:30px 6%;display:flex;justify-content:space-between;align-items:center;font-size:9px;color:#85798c}footer .logo{font-size:25px}#feedback{min-height:20px;font-size:11px;margin-top:15px;color:#51415f}a:focus-visible,button:focus-visible{outline:3px solid #827098;outline-offset:4px}@media(max-width:600px){.hero{grid-template-columns:1fr}.copy{padding:45px 8% 15px}.copy h1{font-size:46px}.art{height:300px}.intro{grid-template-columns:1fr;padding:45px 8%;gap:25px}.features{grid-template-columns:1fr;gap:20px}.gallery{grid-template-columns:1fr}.tile{height:300px}.signup h2{font-size:34px}nav{padding:20px 6%}.story{padding:40px 8%}.hero svg{max-height:330px}footer{gap:15px}}</style></head><body><div class="demo">FICTIONAL BRAND · CAMPAIGN CONCEPT PREVIEW</div><nav><a class="logo" href="#">solune</a><a href="#story">The daily ritual ↗</a></nav><section class="hero"><div class="copy"><div class="label">A moment for you</div><h1>${esc(headline)}</h1><p>Meet Solune Daily Moisturizer. A little space in your day to slow down and make the moment yours.</p><a class="cta" href="#launch">Join the launch list ↗</a></div><div class="art">${product('microsite')}</div></section><section class="intro"><h2>A quieter kind<br>of daily ritual.</h2><p>Some moments deserve a little more room. This campaign imagines a simple daily routine through soft light, warm textures, and thoughtful design. Solune is a fictional brand created for this agency production demo.</p></section><section class="features"><div><span class="label">01 / The product</span><strong>Daily Moisturizer</strong><p>Our featured product, presented through original illustrated packaging.</p></div><div><span class="label">02 / The feeling</span><strong>Room to slow down</strong><p>A creative direction built around quiet moments and intentional routines.</p></div><div><span class="label">03 / The invitation</span><strong>Make it your moment</strong><p>A launch concept that puts a little breathing room into the everyday.</p></div></section><section class="story" id="story"><div class="label">The campaign, in moments</div><h2>Small details. A whole story.</h2><div class="gallery"><div class="tile">${sceneVisual(0)}</div><div class="tile"><span>${esc(headline)}</span>${product('sitegallery')}</div><div class="tile">${sceneVisual(5)}</div></div><p class="caption">Illustrative storyboard and campaign visuals · original SVG artwork</p></section><section class="signup" id="launch"><h2>Your daily ritual starts here.</h2><p>A first look at a quieter kind of launch.</p><button class="cta" id="join">Join the launch list ↗</button><small>Demo interaction · no information is collected</small><div id="feedback" role="status" aria-live="polite"></div></section><footer><span class="logo">solune</span><span>Brand story created with Astoria · Fictional portfolio demo</span></footer><script>document.getElementById('join').addEventListener('click',function(){document.getElementById('feedback').textContent='You’ve reached the demo signup. No data was collected.';this.textContent='Thanks for exploring ✓';});<\/script></body></html>`}
function zip(files){const enc=new TextEncoder(),chunks=[],entries=[];let offset=0;const crc32=data=>{let c=0xffffffff;for(const b of data){c^=b;for(let j=0;j<8;j++)c=(c>>>1)^((c&1)?0xedb88320:0)}return(c^0xffffffff)>>>0};for(const f of files){const name=enc.encode(f.name),data=enc.encode(f.content),crc=crc32(data),header=new Uint8Array(30+name.length),v=new DataView(header.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);header.set(name,30);entries.push({name,data,crc,offset});chunks.push(header,data);offset+=header.length+data.length}const start=offset;for(const e of entries){const h=new Uint8Array(46+e.name.length),v=new DataView(h.buffer);v.setUint32(0,0x02014b50,true);v.setUint16(4,20,true);v.setUint16(6,20,true);v.setUint16(8,0x800,true);v.setUint32(16,e.crc,true);v.setUint32(20,e.data.length,true);v.setUint32(24,e.data.length,true);v.setUint16(28,e.name.length,true);v.setUint32(42,e.offset,true);h.set(e.name,46);chunks.push(h);offset+=h.length}const end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,entries.length,true);v.setUint16(10,entries.length,true);v.setUint32(12,offset-start,true);v.setUint32(16,start,true);chunks.push(end);return new Blob(chunks,{type:'application/zip'})}
window.addEventListener('hashchange',route);route();
